-- v992: контент курса «Адаптация» — День 2 · Рабочий день, воронка, CRM. Сгенерировано gen-academy-adaptation.mjs

INSERT INTO academy_modules (id, course_id, sort, title, intro, gate, active) VALUES
 ($sd$a0000000-0000-0000-0002-000000000002$sd$, $sd$c0000000-0000-0000-0000-000000000002$sd$, 30, $sd$День 2 · Рабочий день, воронка, CRM$sd$, $sd$Алгоритм дня, нормы активности, 16 этапов воронки, чек-лист качества и регламент amoCRM по шагам — то, по чему тебя будут оценивать каждую неделю.$sd$, $sd${"title":"Зачёт дня 2","tasks":["Составил свой план рабочего дня: время старта, блоки звонков, демо, КП, отчёт","Заполнил тестовую сделку в amoCRM: источник, ФИО, сегмент, этап, задача с датой и описанием шага, примечание по образцу","Объяснил наставнику разницу между «взял в работу» и «квалификация пройдена»","Назвал норму дня и единый стандарт времени: лид — 1 час, входящий — до 3-го гудка / перезвон 1 час, мессенджер — 15 минут, email — 2 часа, перезвон после КП — 2 дня"],"result":"Знаешь свои нормы и умеешь работать в CRM."}$sd$::jsonb, true)
ON CONFLICT (id) DO UPDATE SET course_id = EXCLUDED.course_id, sort = EXCLUDED.sort, title = EXCLUDED.title, intro = EXCLUDED.intro, gate = EXCLUDED.gate, active = EXCLUDED.active;

INSERT INTO academy_lessons (id, module_id, sort, title, duration_label, cards, trainer, questions, body_html, links, pass_score, ack_text, active) VALUES
 ($sd$b0000000-0000-0000-0002-000000000201$sd$, $sd$a0000000-0000-0000-0002-000000000002$sd$, 10, $sd$Алгоритм рабочего дня и нормативы$sd$, $sd$15 мин$sd$, '[]'::jsonb, NULL, $sd$[{"q":"Норма дня менеджера:","options":["20 звонков, 2 демо, 1 КП","30 звонков в A/B, 3 демо, 2 КП","50 звонков, 5 демо","10 звонков, 1 демо, 1 КП"],"correct":1},{"q":"Пропустил входящий звонок. Перезвонить нужно…","options":["До конца дня","В течение 1 часа","В течение 2 дней","На следующий день"],"correct":1},{"q":"Когда отправляется КП?","options":["Через 2 дня после демо","В день демо-презентации","После согласия клиента","После получения реквизитов"],"correct":1},{"q":"После отправки КП перезвонить клиенту нужно…","options":["В течение 2 дней","Через неделю","Когда ответит сам","В день отправки"],"correct":0},{"q":"Какой сегмент по приоритизации — «основной рост»?","options":["A","B","C","Все равны"],"correct":1}]$sd$::jsonb, $sd$<h4>Начало дня</h4>
<ul>
<li>Работа и вход в программы — <b>не позднее 9:00</b>.</li>
<li>Проверить CRM на просрочки: звонки после КП, задачи по этапам воронки A/B/C.</li>
<li>Проверить чат и письма от клиентов.</li>
<li>Приоритизация по сегментам: <b>A — срочные задачи, B — основной рост, C — автоматизация</b>.</li>
<li>Подготовить себя: улыбка, настрой.</li>
<li>Входящие звонки — трубка <b>до 3-го гудка</b>. Пропустил — перезвонить <b>в течение 1 часа</b>. Новая заявка — первый контакт <b>в течение 1 часа</b>. Сообщение клиента — ответ за <b>15 минут</b>.</li>
</ul>
<h4>Норма дня</h4>
<div class="kpis"><div><b>30</b><span>холодных звонков в A/B</span></div><div><b>3</b><span>демо-презентации</span></div><div><b>2</b><span>отправленных КП</span></div></div>
<h4>Работа с клиентом</h4>
<ul>
<li>Скрипт квалификации: выявить ЛПР и проверить соответствие дистрибьюторской модели.</li>
<li>Чётко по этапам: <b>квалификация → демо-презентация → КП</b>.</li>
<li>Фиксировать в CRM: количество торговых агентов / экспедиторов, текущие процессы, используемые системы.</li>
<li><b>КП с расчётом лицензий и внедрения — в день демо.</b></li>
<li>После отправки КП — перезвонить <b>в течение 2 дней</b>.</li>
</ul>
<h4>Отчётность</h4>
<ul>
<li>Ежедневный отчёт в WhatsApp: сколько лидов, проведено демо, отправлено КП, новые сделки в B-сегменте. Данные в отчёте = данным в CRM.</li>
<li>Слушать записи своих звонков — искать возражения по ценности продукта.</li>
</ul>
<h4>Каждую неделю</h4>
<ul><li>Анализ конверсии по сегментам A/B/C</li><li>Работа с «тёплыми» клиентами, не купившими в этом месяце</li><li>Сверка с производством по очереди на внедрение / интеграцию</li></ul>
<h4>Каждый месяц</h4>
<ul><li>Сдать план продаж на следующий месяц с разбивкой по сегментам</li><li>Участвовать в оценке удовлетворённости клиентов после запуска</li></ul>$sd$, $sd$[{"t":"Карта менеджера","u":"https://docs.google.com/spreadsheets/d/1W31u54JcVvgy9fpEcxPg-T0bRAeSzk1oLEM8VDupdMo/edit"}]$sd$::jsonb, NULL, NULL, true)
ON CONFLICT (id) DO UPDATE SET module_id = EXCLUDED.module_id, sort = EXCLUDED.sort, title = EXCLUDED.title, duration_label = EXCLUDED.duration_label, questions = EXCLUDED.questions, body_html = EXCLUDED.body_html, links = EXCLUDED.links, pass_score = EXCLUDED.pass_score, ack_text = EXCLUDED.ack_text, active = EXCLUDED.active;

INSERT INTO academy_lessons (id, module_id, sort, title, duration_label, cards, trainer, questions, body_html, links, pass_score, ack_text, active) VALUES
 ($sd$b0000000-0000-0000-0002-000000000202$sd$, $sd$a0000000-0000-0000-0002-000000000002$sd$, 20, $sd$Воронка продаж: 16 этапов$sd$, $sd$20 мин$sd$, '[]'::jsonb, NULL, $sd$[{"q":"Поступила заявка. За сколько нужно позвонить?","options":["За 2 часа","В течение 1 часа","До конца дня","За 2 дня"],"correct":1},{"q":"Какие 4 ответа переводят сделку на этап «Квалификация пройдена»?","options":["Имя, телефон, email, должность","Потребность, бюджет, сроки, полномочия","Сегмент, продукт, конкурент, цена","Агенты, экспедиторы, 1С, ЛПР"],"correct":1},{"q":"Что такое КЭВ в воронке?","options":["Коммерческое предложение","Проведённая демо-встреча","Оплаченный счёт","Вебинар"],"correct":1},{"q":"На каком этапе оказываются самые перспективные сделки после КП?","options":["Взят в работу","Клиент думает / согласует","База заявок","Назначена встреча"],"correct":1},{"q":"Можно ли закрыть сделку как нереализованную без комментария?","options":["Да, если клиент не отвечает","Нет — только с комментарием и по согласованию с руководителем","Да, через 30 дней","Да, для C-сегмента"],"correct":1}]$sd$::jsonb, $sd$<p>Сделка в amoCRM проходит этапы строго по порядку. Здесь — карта воронки: условие входа на каждый этап и кто ещё в нём участвует. Что именно делает менеджер и какие поля заполняет — в уроке 4 «Регламент amoCRM по шагам».</p>
<table class="tbl"><thead><tr><th>Этап</th><th>Когда сделка сюда попадает</th></tr></thead><tbody>
<tr><td>База заявок</td><td>Источник — база контактов, лидогенерация, рекомендации</td></tr>
<tr><td>Поступила заявка</td><td>Клиент оставил заявку через любой канал</td></tr>
<tr><td><b>Взят в работу</b></td><td>Менеджер начал активную проработку: написал, позвонил</td></tr>
<tr><td><b>Квалификация пройдена</b></td><td>Получены ответы на 4 ключевых вопроса: <b>потребность, бюджет, сроки, полномочия</b></td></tr>
<tr><td>Приглашён на вебинар</td><td>Предложено участие в вебинаре эксперта / РОПа</td></tr>
<tr><td>Вебинар проведён (предварительный КЭВ)</td><td>Клиент посетил или посмотрел в записи</td></tr>
<tr><td>Назначена встреча</td><td>Согласовано время демо</td></tr>
<tr><td><b>Встреча проведена (КЭВ)</b></td><td>Клиент увидел решение вживую, сделан сильный оффер</td></tr>
<tr><td>КП / материалы направлены</td><td>Сразу после встречи ушли фоллоу-ап, КП, расчёты</td></tr>
<tr><td>Клиент думает / согласует</td><td>Согласование запущено — самые перспективные сделки</td></tr>
<tr><td>Реквизиты получены</td><td>Клиент согласен, прислал юр. данные</td></tr>
<tr><td>Договор согласован</td><td>Финальный договор утверждён</td></tr>
<tr><td>Счёт выставлен</td><td>Клиенту отправлен счёт</td></tr>
<tr><td>Счёт оплачен → Передано в работу</td><td>Деньги поступили</td></tr>
<tr><td>Закрыто и не реализовано</td><td>Указана причина: дорого, условия, конкуренты…</td></tr>
</tbody></table>
<div class="callout"><b>Ключевая разница.</b> «Взят в работу» — ты начал контакт. «Квалификация пройдена» — ты получил ответы на 4 вопроса: потребность, бюджет, сроки, полномочия. Без ответов сделка на этап квалификации не переходит.</div>
<h4>Кто ещё работает в воронке</h4>
<ul>
<li><b>РОП</b> — контролирует обработку заявок (зависшие на «Взят в работу» — его ответственность), получает уведомление о встрече, при необходимости присутствует на демо или проводит его сам, подключается для усиления КП и ускорения согласования, разбирает успешные и неуспешные сделки в библиотеку продаж.</li>
<li><b>ОКК</b> — контроль качества: проверяет данные на входе и после закрытия звонит клиенту за обратной связью по сделке и работе менеджера.</li>
<li><b>Владелец</b> — получает уведомление об оплаченной сделке, анализирует отчёты РОПа и ОКК.</li>
</ul>
<h4>Роботы CRM работают за тебя</h4>
<p>Автоматическое письмо клиенту при заявке, тегирование лида после квалификации, напоминания за 24 ч / 1 ч / 15 мин до вебинара и встречи, follow-up цепочки после КП (3–5–7 дней), напоминания по счёту (1, 3, 5 дней), автосоздание сделки в воронке «Производство» после оплаты. Твоя задача — держать сделку на верном этапе, тогда автоматизация срабатывает.</p>$sd$, $sd$[{"t":"Воронка продаж и процессы","u":"https://docs.google.com/spreadsheets/d/1f0Q3WoR3xcU5R9z4wYiLe8UAxFEBryI_JP5LfmLxvf8/edit"}]$sd$::jsonb, NULL, NULL, true)
ON CONFLICT (id) DO UPDATE SET module_id = EXCLUDED.module_id, sort = EXCLUDED.sort, title = EXCLUDED.title, duration_label = EXCLUDED.duration_label, questions = EXCLUDED.questions, body_html = EXCLUDED.body_html, links = EXCLUDED.links, pass_score = EXCLUDED.pass_score, ack_text = EXCLUDED.ack_text, active = EXCLUDED.active;

INSERT INTO academy_lessons (id, module_id, sort, title, duration_label, cards, trainer, questions, body_html, links, pass_score, ack_text, active) VALUES
 ($sd$b0000000-0000-0000-0002-000000000203$sd$, $sd$a0000000-0000-0000-0002-000000000002$sd$, 30, $sd$Правила ведения amoCRM и чек-лист качества$sd$, $sd$20 мин$sd$, '[]'::jsonb, NULL, $sd$[{"q":"Сколько сделок без задач или с просроченными задачами допустимо?","options":["Ни одной","Не более 5","Не более 10","Не регламентировано"],"correct":1},{"q":"Нет записи телефонного разговора. Что обязательно?","options":["Ничего","Комментарий, скриншот переписки или запись с телефона","Удалить сделку","Написать РОПу"],"correct":1},{"q":"Что даёт документально подтверждённый отзыв клиента?","options":["Ничего","+1 к KPI","Премию 25 000","Повышение грейда"],"correct":1},{"q":"Что пишется в примечание после каждого общения с клиентом?","options":["Только дата","Тех. требования, сроки решения, конкуренты, бюджет","Настроение клиента","Номер счёта"],"correct":1},{"q":"Обещал клиенту связаться и пропал на 6 рабочих дней. Последствие:","options":["Ничего","Снижение KPI и возможная смена ответственного по сделке","Предупреждение","Штраф 25 000"],"correct":1}]$sd$::jsonb, $sd$<p>По этому чек-листу РОП ставит балл каждую неделю. Какие поля заполнять на каждом этапе — в уроке 4.</p>
<h4>Чек-лист качества работы в CRM — 8 пунктов, оценка 0 / 1 / 2</h4>
<ol>
<li>Заполнены поля: сегмент (A/B/C), количество пользователей, текущие процессы, ЛПР/ФПР, этап воронки.</li>
<li>Сделок без задач или с просроченными задачами — <b>не более 5</b>.</li>
<li>Нет записи звонка — есть комментарий, скриншот переписки или запись с телефона.</li>
<li>Сделки на актуальном этапе воронки.</li>
<li>Как нереализованные закрываются только сделки без 100 % ясности — по согласованию с руководителем.</li>
<li>Закрытие как нереализованной — только с комментарием.</li>
<li>После каждого общения — примечание: технические требования, сроки решения, конкуренты, бюджет.</li>
<li>После завершения сделки — звонок клиенту, чтобы осталось хорошее впечатление.</li>
</ol>
<h4>Регламенты и договоры — что двигает KPI</h4>
<ul>
<li>Достоверная информация клиенту, выполнение обещаний. Просрочка обещания <b>&gt; 5 рабочих дней</b> — снижение KPI, возможна смена ответственного.</li>
<li><b>+1</b> к KPI за каждый документально подтверждённый отзыв.</li>
<li><b>−20</b> за прогул (или штраф по решению руководителя). <b>−1…−3</b> за ошибки в договорах. Минус за недоговорённость с клиентом, задержку внедрения, лишние вопросы коллегам.</li>
</ul>$sd$, $sd$[{"t":"Чек-лист качества работы в CRM","u":"https://docs.google.com/spreadsheets/d/1sUaQzOQyEmV-u8lSdiskkw-FYuBzfJoZfbuUbKNvWpc/edit"}]$sd$::jsonb, NULL, NULL, true)
ON CONFLICT (id) DO UPDATE SET module_id = EXCLUDED.module_id, sort = EXCLUDED.sort, title = EXCLUDED.title, duration_label = EXCLUDED.duration_label, questions = EXCLUDED.questions, body_html = EXCLUDED.body_html, links = EXCLUDED.links, pass_score = EXCLUDED.pass_score, ack_text = EXCLUDED.ack_text, active = EXCLUDED.active;

INSERT INTO academy_lessons (id, module_id, sort, title, duration_label, cards, trainer, questions, body_html, links, pass_score, ack_text, active) VALUES
 ($sd$b0000000-0000-0000-0002-000000000204$sd$, $sd$a0000000-0000-0000-0002-000000000002$sd$, 40, $sd$Как работать в amoCRM: регламент по шагам$sd$, $sd$25 мин$sd$, '[]'::jsonb, NULL, $sd$[{"q":"Срок первого звонка по новой заявке:","options":["10 минут","1 час","1 рабочий день","2 дня"],"correct":1},{"q":"Какая задача поставлена правильно?","options":["«Перезвонить»","«Клиент»","«Связаться — уточнить решение после КП», 07.04","Задача без даты"],"correct":2},{"q":"Какие поля обязательны до перевода в «Квалификация пройдена»?","options":["Имя сервера, тех. специалист","Бюджет, город, должность","Договор, П.О.","Период подписки, внедрение"],"correct":1},{"q":"Сколько максимум дней сделка может стоять на «Клиент принимает решение»?","options":["7","14","30","90"],"correct":2},{"q":"Когда можно закрыть сделку как нереализованную?","options":["Когда клиент не ответил на звонок","После всех 14 касаний, с причиной и комментарием","Через 2 недели тишины","В любой момент по решению менеджера"],"correct":1},{"q":"Пример хорошего примечания:","options":["«Позвонил. Думает.»","«03.04 Звонок. Просит скидку 10 % за год. Ответ до 07.04. Отправил расчёт в WhatsApp.»","«ОК»","«Клиент норм»"],"correct":1},{"q":"Что происходит с премией KPI 3 при выполнении менее 50 % требований?","options":["Снижается на 10 %","Обнуляется","Переносится на следующий месяц","Ничего"],"correct":1}]$sd$::jsonb, $sd$<p>Доступ и вход — в уроке «Инструменты» (день 1). Карта этапов воронки — в уроке 2. Здесь — что менеджер обязан делать в CRM: сроки, задачи, поля, примечания, закрытие.</p>
<h4>Нормативы времени — за них снижают KPI 3</h4>
<table class="tbl"><thead><tr><th>Действие</th><th>Норматив</th></tr></thead><tbody>
<tr><td>Первый звонок по новой заявке</td><td><b>В течение 1 часа</b> с момента поступления. На встрече — перезваниваешь сразу после неё, но в пределах 1 часа</td></tr>
<tr><td>Входящий звонок</td><td>Трубка до 3-го гудка; пропущенный — перезвон в течение 1 часа</td></tr>
<tr><td>Перевод сделки на следующий этап</td><td>В день наступления события</td></tr>
<tr><td>Заполнение полей карточки</td><td>До перевода сделки на следующий этап</td></tr>
<tr><td>Постановка задачи после действия</td><td>Сразу после звонка / встречи</td></tr>
<tr><td>Фиксация результата звонка / встречи</td><td>В течение 30 минут</td></tr>
<tr><td>Ответ на входящее сообщение клиента</td><td>Мессенджеры / Wazzup — 15 минут, email — 2 часа в рабочее время</td></tr>
</tbody></table>
<h4>Главное правило: нет сделки без задачи</h4>
<p>У каждой активной сделки всегда стоит задача с <b>конкретной датой и описанием следующего шага</b>. Сделка без задачи = сделка без контроля = потерянный клиент.</p>
<ul>
<li><b>Правильно:</b> «Связаться — уточнить решение после КП» (07.04) · «Встреча — провести демо продукта» (08.04) · «Связаться — получить подписанный договор» (10.04)</li>
<li><b>Неправильно:</b> «Перезвонить» (зачем?) · «Клиент» (что делать?) · задача без даты (когда?)</li>
</ul>
<h4>Что делать на каждом этапе</h4>
<table class="tbl"><thead><tr><th>Этап</th><th>Действия менеджера</th><th>Обязательные поля до перевода дальше</th></tr></thead><tbody>
<tr><td><b>1. Поступила заявка</b></td><td>Проверить карточку: ФИО, телефон, источник. Заявка из квиза (marquiz) заполняется автоматически — проверить. Перевести в «Взят в работу», задача «Связаться — первичный контакт» на сегодня</td><td>Источник сделки — при создании</td></tr>
<tr><td><b>2. Взят в работу</b></td><td>Позвонить в течение 1 часа, представиться, выяснить потребность, задать квалификационные вопросы. Результат — в примечание. Поставить следующую задачу</td><td>Бюджет · Город · Должность · (желательно) Продукция</td></tr>
<tr><td><b>3. Квалификация пройдена</b></td><td>Подтвердить, что клиент целевой: потребность + бюджет + полномочия. Предложить демо. Задача «Встреча — назначить демо»</td><td>Лицензии (число) · Сегмент A/B/C · (желательно) Какой программой пользуются</td></tr>
<tr><td><b>4. Назначена встреча</b></td><td>Google Calendar, приглашение со ссылкой Zoom / Meet, презентация под клиента, напоминание за 1 день. В примечании: дата, время, формат, кто будет. Задача «Встреча — провести демо» на дату встречи</td><td>—</td></tr>
<tr><td><b>5. Встреча проведена</b></td><td>В течение 30 минут — итоги в примечание: что обсудили, реакция, возражения, договорённости. Отправить follow-up: презентацию, КП, расчёты. Перевести в «КП отправлены». Задача «Связаться — обратная связь по КП» в течение 2 дней</td><td>—</td></tr>
<tr><td><b>6. КП / материалы отправлены</b></td><td>Связаться в течение 2 дней, отработать возражения. Задача «Связаться — уточнить решение»</td><td>Период подписки · Внедрение · Интеграция</td></tr>
<tr><td><b>7. Клиент принимает решение</b></td><td>Контакт <b>не реже 1 раза в 3 дня</b>, каждый — в примечание. При согласии запросить реквизиты. <b>Максимум 30 дней</b> на этапе — дальше согласовать с руководителем: продолжать или закрыть с причиной</td><td>—</td></tr>
<tr><td><b>8. Реквизиты получены</b></td><td>Проверить реквизиты, подготовить и отправить договор. Задача «Связаться — получить подписанный договор»</td><td>—</td></tr>
<tr><td><b>9. Договор согласован</b></td><td>Выставить счёт, перевести в «Счёт выставлен»</td><td>Договор (ссылка) · П.О.</td></tr>
<tr><td><b>10. Счёт выставлен</b></td><td>Контроль оплаты, при задержке — контакт не реже 1 раза в 3 дня</td><td>—</td></tr>
<tr><td><b>11. Счёт оплачен → передано в работу</b></td><td>Проверить, что все поля заполнены. Передать клиента оператору внедрения. В примечании — дата передачи и ФИО оператора</td><td>Имя сервера · Тех. специалист · (желательно) Очередь интеграции</td></tr>
</tbody></table>
<h4>Закрытие сделки как нереализованной</h4>
<ul>
<li>Разрешено <b>только после всех 14 касаний</b>: 7 до демо + 7 после (сами цепочки — день 5, уроки 1–2). Каждое касание — в примечании с номером и типом: «Касание 3/7 до КЭВа — отправил фото аналитики KPI».</li>
<li>Указать причину отказа из списка + комментарий: почему отказался, что можно было сделать иначе.</li>
<li>Поставить задачу на повторный контакт через 3–6 месяцев, если клиент может вернуться.</li>
<li>Без причины закрывать запрещено.</li>
</ul>
<h4>Примечания после каждого контакта</h4>
<p>Дата и тип контакта · краткий итог: о чём договорились, возражения, следующий шаг · для звонка — дозвонился / не дозвонился / перезвонить.</p>
<ul>
<li><b>Хорошо:</b> «03.04 Звонок. Обсудили КП, клиент просит скидку 10 % при оплате за год. Обещал ответ до 07.04. Отправил обновлённый расчёт в WhatsApp.»</li>
<li><b>Плохо:</b> «Позвонил. Думает.»</li>
</ul>
<h4>Что проверяет РОП (KPI 3 — CRM)</h4>
<ul><li>0 сделок без задач</li><li>Обязательные поля заполнены на каждом этапе</li><li>Примечание после каждого контакта</li><li>Первый контакт по заявке в течение 1 часа</li><li>Нет «зависших» сделок — более 30 дней на одном этапе без активности</li></ul>
<div class="callout">Менее 50 % требований по KPI 3 — премия по этому показателю <b>обнуляется</b>. Регламент — приложение к Положению об оплате труда, подписывается при выходе.</div>$sd$, $sd$[{"t":"Регламент работы в CRM (amoCRM) · 2026","u":"https://drive.google.com/file/d/1vDnektJlN8OMfNiD8BrWXIXagcTkaqEi/view"},{"t":"Amo crm · вход и доступ","u":"https://docs.google.com/document/d/1BBXU4ZQhZikS7vKvGL5_kZEEdREbgbKqGsUtUNBodGQ/edit"},{"t":"Воронка продаж и процессы","u":"https://docs.google.com/spreadsheets/d/1f0Q3WoR3xcU5R9z4wYiLe8UAxFEBryI_JP5LfmLxvf8/edit"}]$sd$::jsonb, NULL, NULL, true)
